VID.narration = {"look":{"bar":false},"scenes":[{"dur":10.96,"caps":[[0.5,8.99,"Lecture sixteen. Neural networks. Simple neurons, joined by adjustable weights, that learn instead of following rules."]],"warp":[[0,0],[0.5,0.9],[10.96,4]]},{"dur":28.328,"caps":[[0.5,8.03,"A calculator multiplies huge numbers in a flash."],[8.28,13.17,"It also recalls exact facts for ever."],[13.42,20.31,"But catching a ball or spotting a face? You win."],[20.56,27.37,"Brains are distributed: they learn, generalise and forget."]],"warp":[[0,0],[0.5,0.4],[8.28,3.2],[13.42,6],[20.56,8.8],[28.328,12]]},{"dur":25.124,"caps":[[0.5,3.87,"Your brain holds about 100 billion neurons."],[4.12,8.05,"Each one links to around 10,000 others."],[8.3,16.63,"A synapse can excite or inhibit, like a volume knob."],[16.88,23.13,"Synapses can be strengthened: that is where learning lives."]],"warp":[[0,0],[0.5,0.4],[4.12,3.2],[8.3,6],[16.88,8.8],[25.124,12]]},{"dur":30.047,"caps":[[0.5,8.27,"Symbolic AI: an expert types in IF-THEN rules."],[8.52,15.17,"Easy to read, but fragile outside its scope."],[15.42,21.27,"Connectionism learns numbers, called weights, in a network."],[21.52,28.41,"It generalises and fails gracefully, but is a black box."]],"warp":[[0,0],[0.5,0.4],[8.52,3.2],[15.42,6],[21.52,8.8],[30.047,12]]},{"dur":39.822,"caps":[[0.5,7.79,"A neuron listens, decides, and passes it on."],[8.04,15.01,"McCulloch and Pitts, 1943: inputs times weights, then add."],[15.26,24.07,"1 + 1 = 2 clears a threshold of 1.5, so it fires. That is AND."],[24.32,31.21,"Lower the threshold to 0.5: one input is enough. OR."],[31.46,38.35,"Negative weights inhibit: weights −1, threshold −1.5 give NAND."]],"warp":[[0,0],[0.5,0.4],[8.04,3.2],[15.26,6],[24.32,9.2],[31.46,11.8],[39.822,14]]},{"dur":25.008,"caps":[[0.5,6.67,"Nell's lock lamp should glow when exactly one gate is open."],[6.92,12.45,"That rule is XOR. Its 'on' cases sit in opposite corners."],[12.7,16.71,"One neuron draws one straight line."],[16.96,24.01,"No straight line separates XOR. One neuron can't do it."]],"warp":[[0,0],[0.5,0.4],[6.92,3.2],[12.7,6],[16.96,8.8],[25.008,12]]},{"dur":31.672,"caps":[[0.5,6.91,"Add a hidden layer: OR and NAND feed an AND."],[7.16,14.45,"0 0 and 1 1: the hidden pair disagree, so no light."],[14.7,19.83,"0 1 and 1 0: both agree, so the output fires."],[20.08,24.09,"That is XOR from three neurons."],[24.34,31.07,"The multi-layer perceptron: Rumelhart and McClelland, 1986."]],"warp":[[0,0],[0.5,0.4],[7.16,3.2],[14.7,6.6],[20.08,9.6],[24.34,11.4],[31.672,14]]},{"dur":31.672,"caps":[[0.5,6.35,"Nell's rain brain: 20 hidden neurons, fit score 0.99."],[6.6,13.81,"Lightning knocks out neuron 7. Fit score 0.83."],[14.06,19.03,"Pull one wire from a rule system and it usually fails."],[19.28,24.41,"That is graceful degradation."],[24.66,29.55,"Learned patterns also generalise to new cases and noise."]],"warp":[[0,0],[0.5,0.4],[6.6,3.2],[14.06,6],[19.28,8.8],[24.66,10.6],[31.672,13]]},{"dur":28.746,"caps":[[0.5,7.15,"The case study: rainfall and temperature in, sewer flow out."],[7.4,13.49,"15 rainfall events, January 2010 to October 2012."],[13.74,19.75,"Cross-validation: each split holds one storm back for testing."],[20,26.65,"Train with an EA: each solution is a complete set of weights."]],"warp":[[0,0],[0.5,0.4],[7.4,3.2],[13.74,6],[20,8.8],[28.746,12]]},{"dur":36.665,"caps":[[0.5,6.99,"Fitness is the mean absolute error, MAE. Start: 0.407."],[7.24,14.05,"Mutation adds small Gaussian noise to one weight."],[14.3,22.07,"Generation 20: MAE 0.072, Nash-Sutcliffe 0.92."],[22.32,29.61,"Generation 50: NSE 0.99. Fast at first, then slow."],[29.86,36.11,"NSE: best 1, guessing the average scores 0, no lower limit."]],"warp":[[0,0],[0.5,0.4],[7.24,3.2],[14.3,6],[22.32,8.8],[29.86,11],[36.665,14]]},{"dur":15.34,"caps":[],"warp":[[0,0],[0.5,0.9],[5.08,2],[9.98,3.1],[15.34,9]]}]};
